import type { DocumentComponents } from "@monti-cms/core/render";
import { cms } from "@/cms.server";

/** The collection the theme reads: the name of a collection in `cms.config.ts`. */
type ThemeCollection = Parameters<typeof cms.read.listEntries>[0]["collection"];

export interface BlogThemeConfig {
	/** Your CMS instance (`createCms`), the one the admin and the API route use. Change the import above if it lives elsewhere. */
	cms: typeof cms;
	/** The collection of the posts. */
	collection: ThemeCollection;
	/** Where the list page is mounted, without the language prefix: `/blog`. Used for the links back to the list. Moving the route folder means changing this too. */
	routeBase: string;
	/** Posts per page of the list. */
	pageSize: number;
	/** Name of the relation field that points to the author, or `undefined` for none. */
	authorField?: string;
	/** Name of the relation field that points to the topics (tags), or `undefined` for none. */
	topicsField?: string;
	/** Name of the text field with the summary, shown in the list and used as the page description, or `undefined` for none. */
	excerptField?: string;
	/** Title of the list page, and the label of the link back to it. */
	blogTitle: string;
	/** Public components of your blocks, passed to the renderer (see `DocumentComponents`). */
	components?: DocumentComponents;
	/** How many of the newest posts are searched for the previous and next post of a post. `0` turns the links off. */
	neighborWindow: number;
}

/** The one place to edit: the collection, the route base and the names of your fields. */
export const blogTheme: BlogThemeConfig = {
	cms,
	collection: "post",
	routeBase: "/blog",
	pageSize: 10,
	authorField: "authorId",
	topicsField: "tagIds",
	excerptField: "excerpt",
	blogTitle: "Blog",
	neighborWindow: 100,
};

import { isLocale } from "@monti-cms/core/client";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Pagination } from "./pagination";
import { metadataText, PostMeta } from "./post-meta";
import { blogTheme } from "./theme.config";

/** The route's props. `locale` is there when the page sits under a `[locale]` folder. */
export interface BlogListProps {
	params: Promise<{ locale?: string }>;
	searchParams: Promise<{ page?: string }>;
}

/** The list page: the newest published posts first, paged. The read API supplies each post's URL and its relation names. */
export async function BlogListPage({ params, searchParams }: BlogListProps) {
	const { locale } = await params;
	if (locale !== undefined && !isLocale(locale)) notFound();
	const page = Math.max(1, Math.floor(Number((await searchParams).page ?? 1)) || 1);
	const { items, total, pageSize } = await blogTheme.cms.read.listEntries({
		collection: blogTheme.collection,
		locale,
		page,
		pageSize: blogTheme.pageSize,
	});
	return (
		<main className="mx-auto max-w-2xl px-4 py-12">
			<h1 className="mb-8 font-bold text-3xl">{blogTheme.blogTitle}</h1>
			<ul className="space-y-8">
				{items.map((entry) => {
					const excerpt = metadataText(entry, blogTheme.excerptField);
					return (
						<li key={entry.id}>
							<h2 className="font-semibold text-xl">
								<Link href={entry.path ?? `${blogTheme.routeBase}/${entry.slug}`} className="hover:underline">
									{entry.title ?? entry.slug}
								</Link>
							</h2>
							<PostMeta entry={entry} />
							{excerpt ? <p className="mt-2 text-neutral-800 dark:text-neutral-200">{excerpt}</p> : null}
						</li>
					);
				})}
			</ul>
			{items.length === 0 ? <p className="text-neutral-600 dark:text-neutral-400">No posts yet.</p> : null}
			<Pagination page={page} pageSize={pageSize} total={total} />
		</main>
	);
}

/** The title of the list page. */
export async function generateBlogListMetadata({ params }: Pick<BlogListProps, "params">): Promise<Metadata> {
	const { locale } = await params;
	if (locale !== undefined && !isLocale(locale)) return {};
	return { title: blogTheme.blogTitle };
}

import { isLocale, localizePath } from "@monti-cms/core/client";
import type { ReadEntry } from "@monti-cms/core/read";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound, permanentRedirect } from "next/navigation";
import { ArticleBody } from "@/registry/monti/article-body/article-body";
import { metadataText, PostMeta } from "./post-meta";
import { blogTheme } from "./theme.config";

/** The route's props. `locale` is there when the page sits under a `[locale]` folder. */
export interface BlogPostProps {
	params: Promise<{ locale?: string; slug: string }>;
}

/** The post of the request: a 404 for an unknown, unpublished or foreign-locale address, and a permanent redirect from an old address. */
async function readPost({ params }: BlogPostProps): Promise<ReadEntry> {
	const { locale, slug } = await params;
	if (locale !== undefined && !isLocale(locale)) notFound();
	const result = await blogTheme.cms.read.getEntry({
		collection: blogTheme.collection,
		slug: decodeURIComponent(slug),
		locale,
	});
	if (result.status === "not_found") notFound();
	if (result.status === "redirect") permanentRedirect(result.path ?? result.slug);
	return result.entry;
}

/** The post before and after this one (older and newer), looked up among the newest `neighborWindow` posts. None when the post is outside that window. */
async function neighborsOf(entry: ReadEntry): Promise<{ newer?: ReadEntry; older?: ReadEntry }> {
	if (blogTheme.neighborWindow <= 0) return {};
	const { items } = await blogTheme.cms.read.listEntries({
		collection: blogTheme.collection,
		locale: entry.locale,
		pageSize: blogTheme.neighborWindow,
	});
	const index = items.findIndex((item) => item.id === entry.id);
	return index === -1 ? {} : { newer: items[index - 1], older: items[index + 1] };
}

function Neighbor({ entry, label, align }: { entry: ReadEntry; label: string; align: "left" | "right" }) {
	return (
		<Link
			href={entry.path ?? `${blogTheme.routeBase}/${entry.slug}`}
			className={`block rounded-lg border border-neutral-300 p-4 hover:bg-neutral-100 dark:border-neutral-700 dark:hover:bg-neutral-900 ${align === "right" ? "text-right" : ""}`}
		>
			<span className="block text-neutral-600 text-xs dark:text-neutral-400">{label}</span>
			<span className="font-medium">{entry.title ?? entry.slug}</span>
		</Link>
	);
}

/** The detail page: title, byline (date, author, topics), a table of contents and the body (`ArticleBody`), and the newer and older post. */
export async function BlogPostPage(props: BlogPostProps) {
	const entry = await readPost(props);
	const { newer, older } = await neighborsOf(entry);
	return (
		<main className="mx-auto max-w-2xl px-4 py-12">
			<Link
				href={localizePath(entry.locale, blogTheme.routeBase)}
				className="text-neutral-600 text-sm hover:underline dark:text-neutral-400"
			>
				← {blogTheme.blogTitle}
			</Link>
			<h1 className="mt-4 mb-2 font-bold text-3xl">{entry.title ?? entry.slug}</h1>
			<div className="mb-8">
				<PostMeta entry={entry} />
			</div>
			<ArticleBody entry={entry} components={blogTheme.components} />
			{newer || older ? (
				<nav aria-label="More posts" className="mt-12 grid gap-4 sm:grid-cols-2">
					{older ? <Neighbor entry={older} label="Older post" align="left" /> : <span />}
					{newer ? <Neighbor entry={newer} label="Newer post" align="right" /> : <span />}
				</nav>
			) : null}
		</main>
	);
}

/** Title, description (the excerpt) and Open Graph of the post. An unknown address gets no metadata: the page itself answers 404 or redirects. */
export async function generateBlogPostMetadata({ params }: BlogPostProps): Promise<Metadata> {
	const { locale, slug } = await params;
	if (locale !== undefined && !isLocale(locale)) return {};
	const result = await blogTheme.cms.read.getEntry({
		collection: blogTheme.collection,
		slug: decodeURIComponent(slug),
		locale,
	});
	if (result.status !== "found") return {};
	const { entry } = result;
	const title = entry.title ?? entry.slug;
	const description = metadataText(entry, blogTheme.excerptField);
	return {
		title,
		description,
		alternates: entry.path ? { canonical: entry.path } : undefined,
		openGraph: {
			type: "article",
			title,
			description,
			publishedTime: entry.publishedAt?.toISOString(),
			modifiedTime: entry.updatedAt.toISOString(),
		},
	};
}

import type { ReadEntry } from "@monti-cms/core/read";
import { blogTheme } from "./theme.config";

/** The text of a metadata field, or `undefined` when the field is not set or not text. */
export function metadataText(entry: ReadEntry, field: string | undefined): string | undefined {
	const value = field ? (entry.metadata as Record<string, unknown>)[field] : undefined;
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

/** The titles of the targets of a relation field. */
export const relationTitles = (entry: ReadEntry, field: string | undefined): string[] =>
	(field ? (entry.relations[field] ?? []) : []).flatMap((target) => (target.title ? [target.title] : []));

const dateOf = (date: Date) => date.toISOString().slice(0, 10);

/** The byline: the publish date, the author and the topics, in a muted line. */
export function PostMeta({ entry }: { entry: ReadEntry }) {
	const author = relationTitles(entry, blogTheme.authorField)[0];
	const topics = relationTitles(entry, blogTheme.topicsField);
	const parts = [...(author ? [author] : []), ...topics.map((topic) => `#${topic}`)];
	return (
		<p className="text-neutral-600 text-sm dark:text-neutral-400">
			{entry.publishedAt ? <time dateTime={dateOf(entry.publishedAt)}>{dateOf(entry.publishedAt)}</time> : null}
			{entry.publishedAt && parts.length > 0 ? " · " : null}
			{parts.join(" · ")}
		</p>
	);
}

import Link from "next/link";

/** Newer and older links of a paged list. The links are relative (`?page=2`), so they keep the path and the language of the page. */
export function Pagination({ page, pageSize, total }: { page: number; pageSize: number; total: number }) {
	const hasOlder = page * pageSize < total;
	if (page <= 1 && !hasOlder) return null;
	const link = "underline underline-offset-4 hover:text-neutral-600 dark:hover:text-neutral-300";
	return (
		<nav aria-label="Pagination" className="mt-10 flex items-center justify-between text-sm">
			{page > 1 ? (
				<Link href={page === 2 ? "?" : `?page=${page - 1}`} className={link} rel="prev">
					Newer posts
				</Link>
			) : (
				<span />
			)}
			<span className="text-neutral-600 dark:text-neutral-400">Page {page}</span>
			{hasOlder ? (
				<Link href={`?page=${page + 1}`} className={link} rel="next">
					Older posts
				</Link>
			) : (
				<span />
			)}
		</nav>
	);
}

import { BlogListPage, generateBlogListMetadata } from "@/registry/monti/blog-theme/blog-list";

// Route segment settings are written here, not re-exported: the posts are read from the database on each request.
export const dynamic = "force-dynamic";

export const generateMetadata = generateBlogListMetadata;

export default BlogListPage;

import { BlogPostPage, generateBlogPostMetadata } from "@/registry/monti/blog-theme/blog-post";

// Route segment settings are written here, not re-exported: the posts are read from the database on each request.
export const dynamic = "force-dynamic";

export const generateMetadata = generateBlogPostMetadata;

export default BlogPostPage;
